/**
 * Timestamp helpers: ISO round-tripping, relative formatting, due-date and
 * digest-window arithmetic.
 *
 * Every timestamp in Taskflow is an `IsoTimestamp` (a UTC ISO-8601 string in
 * a SQLite text column). Nothing outside this module constructs a `Date` from
 * a stored value — going through `parseIso()` keeps the "what if it is
 * malformed" answer in one place.
 */
import type { IsoTimestamp } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

const MINUTE_MS = 60_000;
const HOUR_MS = 60 * MINUTE_MS;
const DAY_MS = 24 * HOUR_MS;
const WEEK_MS = 7 * DAY_MS;

export function now(): IsoTimestamp {
  return toIsoTimestamp(new Date());
}

/** Parses a stored timestamp; throws rather than yielding an Invalid Date. */
export function parseIso(value: IsoTimestamp): Date {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new RangeError(`Malformed IsoTimestamp: "${value}"`);
  }
  return date;
}

function plural(count: number, unit: string): string {
  return `${count} ${unit}${count === 1 ? "" : "s"}`;
}

/**
 * "just now" / "5 minutes ago" / "in 2 days" — the wording the activity feed,
 * issue cards and comment headers all use.
 */
export function formatRelative(
  value: IsoTimestamp,
  reference: Date = new Date(),
): string {
  const deltaMs = parseIso(value).getTime() - reference.getTime();
  const past = deltaMs < 0;
  const abs = Math.abs(deltaMs);

  const phrase = ((): string => {
    if (abs < MINUTE_MS) return "just now";
    if (abs < HOUR_MS) return plural(Math.floor(abs / MINUTE_MS), "minute");
    if (abs < DAY_MS) return plural(Math.floor(abs / HOUR_MS), "hour");
    if (abs < WEEK_MS) return plural(Math.floor(abs / DAY_MS), "day");
    if (abs < 30 * DAY_MS) return plural(Math.floor(abs / WEEK_MS), "week");
    if (abs < 365 * DAY_MS) return plural(Math.floor(abs / (30 * DAY_MS)), "month");
    return plural(Math.floor(abs / (365 * DAY_MS)), "year");
  })();

  if (phrase === "just now") return phrase;
  return past ? `${phrase} ago` : `in ${phrase}`;
}

/** Absolute calendar rendering, e.g. "12 Mar 2026", in the given timezone. */
export function formatDate(value: IsoTimestamp, timezone = "UTC"): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: timezone,
  }).format(parseIso(value));
}

function dateParts(
  date: Date,
  formatter: Intl.DateTimeFormat,
): Record<string, string> {
  return Object.fromEntries(
    formatter.formatToParts(date).map(({ type, value }) => [type, value]),
  );
}

function dateString(parts: Record<string, string>): string {
  return `${parts.year?.padStart(4, "0")}-${parts.month}-${parts.day}`;
}

function dateFormatter(timeZone: string): Intl.DateTimeFormat {
  return new Intl.DateTimeFormat("en-US-u-ca-iso8601-nu-latn", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  });
}

/** The workspace's `YYYY-MM-DD` calendar date for an instant. */
export function localDate(value: IsoTimestamp, timeZone: string): string {
  return dateString(dateParts(parseIso(value), dateFormatter(timeZone)));
}

/**
 * Finds the first instant belonging to a local calendar date. Searching for
 * the date boundary also handles zones whose clocks jump over local midnight.
 */
export function startOfLocalDate(
  day: string,
  timeZone: string,
): IsoTimestamp {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) {
    throw new RangeError(`Malformed local date: "${day}"`);
  }
  const nominal = new Date(`${day}T00:00:00.000Z`);
  if (Number.isNaN(nominal.getTime()) || nominal.toISOString().slice(0, 10) !== day) {
    throw new RangeError(`Malformed local date: "${day}"`);
  }

  const formatter = dateFormatter(timeZone);
  const target = day;
  let low = nominal.getTime() - 48 * HOUR_MS;
  let high = nominal.getTime() + 48 * HOUR_MS;

  while (dateString(dateParts(new Date(low), formatter)) >= target) {
    low -= 24 * HOUR_MS;
  }
  while (dateString(dateParts(new Date(high), formatter)) < target) {
    high += 24 * HOUR_MS;
  }

  // Find the first millisecond whose local date is this date or later.
  while (high - low > 1) {
    const middle = low + Math.floor((high - low) / 2);
    if (dateString(dateParts(new Date(middle), formatter)) >= target) {
      high = middle;
    } else {
      low = middle;
    }
  }

  if (dateString(dateParts(new Date(high), formatter)) !== target) {
    throw new RangeError(`Local date does not exist in ${timeZone}: ${day}`);
  }
  return toIsoTimestamp(new Date(high));
}

/** UTC instant at which the workspace's current local calendar day began. */
export function startOfLocalDay(
  reference: Date,
  timeZone: string,
): IsoTimestamp {
  const referenceStamp = toIsoTimestamp(reference);
  return startOfLocalDate(localDate(referenceStamp, timeZone), timeZone);
}

/** True when the local calendar day containing the due date has ended. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  if (dueAt === null) return false;
  const referenceStamp = toIsoTimestamp(reference);
  return localDate(dueAt, timeZone) < localDate(referenceStamp, timeZone);
}

export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * The local-clock window a digest covers, ending at the most recent configured
 * local hour. The endpoints are resolved independently, so a window spanning
 * a daylight-saving change can be 23 or 25 hours long.
 */
export function digestWindow(
  digestHourUtc: number,
  reference: Date,
  timeZone = "UTC",
): { start: IsoTimestamp; end: IsoTimestamp } {
  if (!Number.isInteger(digestHourUtc) || digestHourUtc < 0 || digestHourUtc > 23) {
    throw new RangeError(`digestHourUtc must be 0-23, got ${digestHourUtc}`);
  }

  const referenceStamp = toIsoTimestamp(reference);
  const formatter = new Intl.DateTimeFormat("en-US-u-ca-iso8601-nu-latn", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    hourCycle: "h23",
    minute: "2-digit",
    second: "2-digit",
  });
  const currentParts = dateParts(reference, formatter);
  const today = dateString(currentParts);
  const todayHour = Number(currentParts.hour);

  let endDay = todayHour >= digestHourUtc ? today : shiftCalendarDate(today, -1);
  let endCandidates = localHourCandidates(endDay, digestHourUtc, timeZone);
  const notAfterReference = endCandidates.filter(
    (candidate) => candidate <= reference.getTime(),
  );
  if (notAfterReference.length > 0) {
    endCandidates = notAfterReference;
  } else if (endDay === today) {
    endDay = shiftCalendarDate(today, -1);
    endCandidates = localHourCandidates(endDay, digestHourUtc, timeZone);
  }
  const endMs = endCandidates.at(-1);
  if (endMs === undefined) {
    throw new RangeError(
      `Local hour ${digestHourUtc}:00 does not exist for ${endDay} in ${timeZone}`,
    );
  }

  const startDay = shiftCalendarDate(endDay, -1);
  const startCandidates = localHourCandidates(startDay, digestHourUtc, timeZone);
  const startMs = startCandidates[0];
  if (startMs === undefined) {
    throw new RangeError(
      `Local hour ${digestHourUtc}:00 does not exist for ${startDay} in ${timeZone}`,
    );
  }

  return {
    start: toIsoTimestamp(new Date(startMs)),
    end: toIsoTimestamp(new Date(endMs)),
  };
}

function shiftCalendarDate(day: string, amount: number): string {
  const date = new Date(`${day}T00:00:00.000Z`);
  date.setUTCDate(date.getUTCDate() + amount);
  return date.toISOString().slice(0, 10);
}

function localHourCandidates(
  day: string,
  hour: number,
  timeZone: string,
): number[] {
  const [year, month, date] = day.split("-").map(Number);
  const wallTime = Date.UTC(year, month - 1, date, hour);
  const wallTime = Date.UTC(year, month - 1, date, hour);
  const formatter = new Intl.DateTimeFormat("en-US-u-ca-iso8601-nu-latn", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    hourCycle: "h23",
    minute: "2-digit",
    second: "2-digit",
  });

  const offsets = new Set<number>();
  for (let delta = -48 * HOUR_MS; delta <= 48 * HOUR_MS; delta += 6 * HOUR_MS) {
    const sample = wallTime + delta;
    const parts = dateParts(new Date(sample), formatter);
    const localAsUtc = Date.UTC(
      Number(parts.year),
      Number(parts.month) - 1,
      Number(parts.day),
      Number(parts.hour),
      Number(parts.minute),
      Number(parts.second),
    );
    offsets.add(localAsUtc - Math.floor(sample / 1000) * 1000);
  }

  const candidates = new Set<number>();
  const afterGap: Array<{ instant: number; wallTime: number }> = [];
  for (const offset of offsets) {
    const candidate = wallTime - offset;
    const parts = dateParts(new Date(candidate), formatter);
    if (dateString(parts) !== day) continue;

    const candidateWallTime = Date.UTC(
      Number(parts.year),
      Number(parts.month) - 1,
      Number(parts.day),
      Number(parts.hour),
      Number(parts.minute),
      Number(parts.second),
    );
    if (candidateWallTime === wallTime) candidates.add(candidate);
    else if (candidateWallTime > wallTime) {
      afterGap.push({ instant: candidate, wallTime: candidateWallTime });
    }
  }
  if (candidates.size === 0 && afterGap.length > 0) {
    const firstAfterGap = afterGap.sort(
      (a, b) => a.wallTime - b.wallTime || a.instant - b.instant,
    )[0];
    if (firstAfterGap) candidates.add(firstAfterGap.instant);
  }
  return [...candidates].sort((a, b) => a - b);
}

