"use client";

/**
 * One row of `IssueList`; renders the archive control only when permitted.
 *
 * A Client Component because the title and the archive control are buttons:
 * the issues pages render `IssueList` on the server, and a `<button onClick>`
 * produced there is a render error even when the callback prop is absent —
 * the inline arrow is still a function on a DOM element.
 *
 * Must call (do not reimplement): can
 */
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { TableCell, TableRow } from "@/components/ui/table";
import { cn } from "@/lib/cn";
import { formatRelative, isOverdue } from "@/lib/date";
import { humanizePriority, humanizeStatus } from "@/lib/format";
import { can } from "@/lib/permissions";
import type { IssueId } from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { issueResource } from "../permission/resources";
import { PRIORITY_TONE, STATUS_TONE } from "./issue-tone";

export type IssueRowProps = {
  issue: Issue;
  actor: Actor;
  assignee: User | null;
  timeZone?: string;
  onSelect?: (issueId: IssueId) => void;
  /** Optional: when provided the archive control is offered to actors who
   *  pass `issue:archive` for this row. */
  onArchive?: (issueId: IssueId) => void;
};

export function IssueRow(props: IssueRowProps): ReactElement | null {
  const {
    issue,
    actor,
    assignee,
    onSelect,
    onArchive,
    timeZone = "UTC",
  } = props;
  const resource = issueResource(issue);
  // Ownership escalations mean the author or assignee may archive their own
  // issue even below the matrix rank — `can()` already knows that.
  const mayArchive = can(actor, "issue:archive", resource);
  const overdue =
    issue.archivedAt === null &&
    issue.status !== "done" &&
    issue.status !== "canceled" &&
    isOverdue(issue.dueAt, new Date(), timeZone);

  return (
    <TableRow className={cn(issue.archivedAt !== null && "opacity-60")}>
      <TableCell className="w-16 text-neutral-500">#{issue.number}</TableCell>

      <TableCell>
        <button
          type="button"
          className="text-left font-medium hover:underline"
          onClick={() => onSelect?.(issue.id)}
        >
          {issue.title}
        </button>
      </TableCell>

      <TableCell className="w-32">
        <Badge tone={STATUS_TONE[issue.status]} size="sm">
          {humanizeStatus(issue.status)}
        </Badge>
      </TableCell>

      <TableCell className="w-28">
        <Badge tone={PRIORITY_TONE[issue.priority]} size="sm">
          {humanizePriority(issue.priority)}
        </Badge>
      </TableCell>

      <TableCell className="w-40">
        {assignee !== null ? (
          <span className="flex items-center gap-2">
            <Avatar name={assignee.name} src={assignee.avatarUrl} size="xs" />
            {assignee.name}
          </span>
        ) : (
          <span className="text-neutral-500">Unassigned</span>
        )}
      </TableCell>

      <TableCell className={cn("w-32 text-sm", overdue && "text-red-600")}>
        {issue.dueAt === null ? "—" : formatRelative(issue.dueAt)}
      </TableCell>

      <TableCell className="w-24 text-right">
        {mayArchive && onArchive !== undefined && issue.archivedAt === null ? (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onArchive(issue.id)}
          >
            Archive
          </Button>
        ) : null}
      </TableCell>
    </TableRow>
  );
}

"use client";

/**
 * Due-date control that flags overdue values.
 */
import { DatePicker } from "@/components/ui/date-picker";
import { isOverdue, localDate, startOfLocalDate } from "@/lib/date";
import type { IsoTimestamp } from "@/types/common";
import type { ReactElement } from "react";

export type IssueDueDateFieldProps = {
  value: IsoTimestamp | null;
  onChange: (value: IsoTimestamp | null) => void;
  timeZone?: string;
};

/** The picker speaks `YYYY-MM-DD`; the domain stores full ISO timestamps. */
export function toDateInputValue(
  value: IsoTimestamp | null,
  timeZone = "UTC",
): string | null {
  return value === null ? null : localDate(value, timeZone);
}

export function fromDateInputValue(
  value: string | null,
  timeZone = "UTC",
): IsoTimestamp | null {
  if (value === null || value.length === 0) return null;
  return startOfLocalDate(value, timeZone);
}

export function IssueDueDateField(
  props: IssueDueDateFieldProps,
): ReactElement | null {
  const timeZone = props.timeZone ?? "UTC";
  const overdue = isOverdue(props.value, new Date(), timeZone);

  return (
    <div className="space-y-1">
      <DatePicker
        value={toDateInputValue(props.value, timeZone)}
        placeholder="No due date"
        onChange={(value) =>
          props.onChange(fromDateInputValue(value, timeZone))
        }
      />
      {overdue ? (
        <p className="text-xs text-red-600">This issue is past its due date.</p>
      ) : null}
    </div>
  );
}

/**
 * Virtualised issue list; hides row actions the actor may not perform.
 *
 * Must call (do not reimplement): can
 */
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table,
  TableBody,
  TableHead,
  TableHeaderCell,
  TableRow,
} from "@/components/ui/table";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import type { IssueId } from "@/types/common";
import type { IssueWithRelations } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { IssueRow } from "./issue-row";

export type IssueListProps = {
  issues: readonly IssueWithRelations[];
  actor: Actor;
  timeZone?: string;
  emptyLabel?: string;
  onArchive?: (issueId: IssueId) => void;
  /** Assignee lookup for the rows; the page joins users once, not per row. */
  users?: Readonly<Record<string, User>>;
};

const COLUMNS: readonly string[] = [
  "#",
  "Title",
  "Status",
  "Priority",
  "Assignee",
  "Due",
  "",
];

export function IssueList(props: IssueListProps): ReactElement | null {
  const {
    issues,
    actor,
    emptyLabel,
    onArchive,
    users = {},
    timeZone = "UTC",
  } = props;

  // One coarse check for the whole list: an actor who cannot read issues at
  // all sees the empty state rather than a table of hidden rows.
  if (!can(actor, "issue:read", organizationResource(actor.orgId))) {
    return (
      <EmptyState
        title="No access"
        description="Your role does not include issue access in this organization."
      />
    );
  }

  if (issues.length === 0) {
    return (
      <EmptyState
        title={emptyLabel ?? "No issues match this filter"}
        description="Adjust the filters or create the first issue."
      />
    );
  }

  // Live rows first; archived ones stay visible but sink to the bottom.
  const ordered = [...issues].sort((a, b) => {
    const archivedDelta =
      Number(isArchived(a.issue)) - Number(isArchived(b.issue));
    if (archivedDelta !== 0) return archivedDelta;
    return b.issue.updatedAt.localeCompare(a.issue.updatedAt);
  });

  return (
    <Table caption="Issues">
      <TableHead>
        <TableRow>
          {COLUMNS.map((column, index) => (
            <TableHeaderCell key={column.length === 0 ? `col-${index}` : column}>
              {column}
            </TableHeaderCell>
          ))}
        </TableRow>
      </TableHead>
      <TableBody>
        {ordered.map(({ issue }) => (
          <IssueRow
            key={issue.id}
            issue={issue}
            actor={actor}
            timeZone={timeZone}
            assignee={
              issue.assigneeId === null ? null : users[issue.assigneeId] ?? null
            }
            {...(onArchive !== undefined ? { onArchive } : {})}
          />
        ))}
      </TableBody>
    </Table>
  );
}

/**
 * Project lifecycle including the project-count quota and the cascade that archives a project's issues.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, uniqueSlug, projectKeyFromName
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { projectKeyFromName, uniqueSlug } from "@/lib/slug";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import {
  actorEnvelope,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  ArchiveProjectInput,
  CreateProjectInput,
  ListProjectsInput,
  UpdateProjectInput,
} from "@/schemas/project";
import type { OrgId, Page, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { Project, ProjectWithStats } from "@/types/project";

/**
 * Creates a project once the plan still has room for one. The key is derived
 * from the name when the caller left it blank, so the issue numbering scheme
 * (`TF-12`) is never invented at the call site.
 */
export async function createProject(
  actor: Actor,
  input: CreateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const slug = await suggestProjectSlug(input.orgId, input.name);

  const project = await projectRepo.insertProject({
    ...input,
    slug,
    key: input.key || projectKeyFromName(input.name),
  });

  await emit("project.created", {
    ...actorEnvelope(actor),
    projectId: project.id,
    name: project.name,
    slug: project.slug,
  });

  return project;
}

export async function updateProject(
  actor: Actor,
  input: UpdateProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:update", projectResource(project));
  assertNotArchived("Project", project.id, project);

  return projectRepo.updateProject(input);
}

/**
 * Archiving a project cascades to its issues by default — leaving live issues
 * behind an archived project is the drift this flag exists to prevent.
 */
export async function archiveProject(
  actor: Actor,
  input: ArchiveProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));
  assertNotArchived("Project", project.id, project);

  const issuesArchived = input.archiveIssues
    ? await issueRepo.archiveIssuesForProject(input.orgId, input.projectId)
    : 0;

  const archived = await projectRepo.archiveProject(
    input.orgId,
    input.projectId,
  );

  await emit("project.archived", {
    ...actorEnvelope(actor),
    projectId: archived.id,
    issuesArchived,
  });

  return archived;
}

/** Restore does not un-archive the issues: they are restored individually. */
export async function restoreProject(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<Project> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "project:archive", projectResource(project));

  const restored = await projectRepo.restoreProject(orgId, projectId);

  await emit("project.restored", {
    ...actorEnvelope(actor),
    projectId: restored.id,
  });

  return restored;
}

export async function getProject(
  actor: Actor,
