export function IssueForm(props: IssueFormProps): ReactElement | null {
  const {
    orgId,
    projectId,
    defaultValues,
    members,
    labels,
    onSubmit,
    timeZone = "UTC",
  } = props;

  const form = useForm({
    resolver: zodResolver(createIssueSchema),
    defaultValues: {
      orgId,
      projectId,
      title: "",
      description: null,
      status: "backlog",
      priority: "none",
      assigneeId: null,
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
      ...defaultValues,
    },
  });

  const { submit, pending, error } = useFormAction(onSubmit, {
    onSuccess: () => form.reset(),
  });

  const values = useWatch({ control: form.control });
