/**
 * One status column with a drop target.
 *
 * Must call (do not reimplement): can
 */
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/cn";
import { humanizeStatus } from "@/lib/format";
import { can } from "@/lib/permissions";
import type { IssueId } from "@/types/common";
import type { IssueBoardColumn } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { issueResource } from "../permission/resources";
import { STATUS_TONE } from "../issue/issue-tone";
import { KANBAN_DRAG_TYPE, KanbanCard } from "./kanban-card";

export type KanbanColumnProps = {
  column: IssueBoardColumn;
  actor: Actor;
  timeZone?: string;
  onDrop: (issueId: IssueId, toIndex: number) => void;
  /** Assignee lookup so cards do not each re-join the member list. */
  users?: Readonly<Record<string, User>>;
};

export function KanbanColumn(props: KanbanColumnProps): ReactElement | null {
  const { column, actor, onDrop, users = {}, timeZone = "UTC" } = props;

  return (
    <section
      className={cn(
        "kanban-column flex w-64 shrink-0 flex-col gap-2 rounded bg-neutral-50 p-2",
      )}
      onDragOver={(event) => event.preventDefault()}
      onDrop={(event) => {
        event.preventDefault();
        const issueId = event.dataTransfer.getData(KANBAN_DRAG_TYPE);
        if (issueId.length === 0) return;
        onDrop(issueId as IssueId, column.issues.length);
      }}
    >
      <header className="flex items-center justify-between">
        <Badge tone={STATUS_TONE[column.status]} size="sm">
          {humanizeStatus(column.status)}
        </Badge>
        <span className="text-xs text-neutral-500">{column.total}</span>
      </header>

      {column.issues.map((issue) => (
        <KanbanCard
          key={issue.id}
          issue={issue}
          timeZone={timeZone}
          assignee={
            issue.assigneeId === null ? null : users[issue.assigneeId] ?? null
          }
          // Dragging is a status change: only actors who may update this
          // particular issue get a grab cursor.
          draggable={can(actor, "issue:update", issueResource(issue))}
        />
      ))}

      {column.issues.length === 0 ? (
        <p className="px-1 py-4 text-center text-xs text-neutral-400">
          Nothing here
        </p>
      ) : null}
    </section>
  );
}

/**
 * Compact issue summary tile used by lists and the board.
 */
import Link from "next/link";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { cn } from "@/lib/cn";
import { formatRelative, isOverdue } from "@/lib/date";
import { humanizePriority, humanizeStatus } from "@/lib/format";
import type { Issue, IssueLabel, IssuePriority } from "@/types/issue";
import type { User } from "@/types/member";
import type { ReactElement } from "react";
import { PRIORITY_TONE, STATUS_TONE } from "./issue-tone";

export type IssueCardProps = {
  issue: Issue;
  assignee?: User | null;
  labels?: readonly IssueLabel[];
  href: string;
  compact?: boolean;
  timeZone?: string;
};

/** Priorities worth shouting about; `none`/`low` stay silent on a card. */
function shouldShowPriority(priority: IssuePriority): boolean {
  return priority !== "none" && priority !== "low";
}

export function IssueCard(props: IssueCardProps): ReactElement | null {
  const {
    issue,
    assignee = null,
    labels = [],
    href,
    compact = false,
    timeZone = "UTC",
  } = props;
  const overdue =
    issue.archivedAt === null &&
    issue.status !== "done" &&
    issue.status !== "canceled" &&
    isOverdue(issue.dueAt, new Date(), timeZone);

  return (
    <Card padded={!compact} className="issue-card">
      <div className={cn("flex items-start gap-3", compact && "text-sm")}>
        <div className="min-w-0 flex-1">
          <Link href={href} className="block font-medium hover:underline">
            <span className="mr-2 text-neutral-500">#{issue.number}</span>
            {issue.title}
          </Link>

          <div className="mt-1 flex flex-wrap items-center gap-2">
            <Badge tone={STATUS_TONE[issue.status]} size="sm">
              {humanizeStatus(issue.status)}
            </Badge>

            {shouldShowPriority(issue.priority) ? (
              <Badge tone={PRIORITY_TONE[issue.priority]} size="sm">
                {humanizePriority(issue.priority)}
              </Badge>
            ) : null}

            {labels.map((label) => (
              <Badge key={label.id} tone="neutral" size="sm">
                {label.name}
              </Badge>
            ))}

            {issue.dueAt !== null ? (
              <span className={cn("text-xs", overdue && "text-red-600")}>
                {overdue ? "overdue " : "due "}
                {formatRelative(issue.dueAt)}
              </span>
            ) : null}

            {issue.archivedAt !== null ? (
              <Badge tone="warning" size="sm">
                Archived
              </Badge>
            ) : null}
          </div>
        </div>

        {assignee !== null ? (
          <Avatar name={assignee.name} src={assignee.avatarUrl} size="sm" />
        ) : (
          <Badge tone="neutral" size="sm">
            Unassigned
          </Badge>
        )}
      </div>
    </Card>
  );
}

