/**
 * Drag-and-drop board; renders nothing unless the `kanban_board` flag is on.
 *
 * Must call (do not reimplement): isEnabled, can
 */
import { useState, useTransition } from "react";
import { EmptyState } from "@/components/ui/empty-state";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import type { MoveIssueInput } from "@/schemas/issue";
import type { ActionResult } from "@/types/api";
import type { IssueId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Issue, IssueBoardColumn, IssueStatus } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { organizationResource } from "../permission/resources";
import { moveIssueInColumns, orderColumns } from "./board-model";
import { KanbanColumn } from "./kanban-column";

export type KanbanBoardProps = {
  columns: readonly IssueBoardColumn[];
  actor: Actor;
  flags: FeatureFlagSnapshot;
  timeZone?: string;
  onMove: (input: MoveIssueInput) => Promise<ActionResult<Issue>>;
  /** Assignee lookup passed straight through to the cards. */
  users?: Readonly<Record<string, User>>;
};

export function KanbanBoard(props: KanbanBoardProps): ReactElement | null {
  const { columns, actor, flags, onMove, users, timeZone = "UTC" } = props;

  // The snapshot the layout serialised is the fast path; `isEnabled()` is the
  // fallback for a snapshot that predates the flag.
  const boardEnabled =
    flags.kanban_board === true ||
    isEnabled("kanban_board", {
      orgId: actor.orgId,
      userId: actor.userId,
      plan: "free",
      role: actor.role,
    });

  const [local, setLocal] = useState<readonly IssueBoardColumn[] | null>(null);
  const [pending, startTransition] = useTransition();

  if (!boardEnabled) return null;

  const mayMove = can(actor, "issue:update", organizationResource(actor.orgId));
  const rendered = orderColumns(local ?? columns);

  if (rendered.every((column) => column.issues.length === 0)) {
    return (
      <EmptyState
        title="This board is empty"
        description="Create an issue to see it here."
      />
    );
  }

  function handleDrop(
    toStatus: IssueStatus,
    issueId: IssueId,
    toIndex: number,
  ): void {
    if (!mayMove) return;
    // Land the card immediately, then let the action reconcile; on failure the
    // local override is dropped and the server columns win again.
    const optimistic = moveIssueInColumns(rendered, issueId, toStatus, toIndex);
    setLocal(optimistic);

    startTransition(async () => {
      const result = await onMove({
        orgId: actor.orgId,
        issueId,
        toStatus,
        toIndex,
      });
      if (!result.ok) setLocal(null);
    });
  }

  return (
    <div
      className="kanban-board flex gap-3 overflow-x-auto"
      aria-busy={pending}
    >
      {rendered.map((column) => (
        <KanbanColumn
          key={column.status}
          column={column}
          actor={actor}
          timeZone={timeZone}
          onDrop={(issueId, toIndex) =>
            handleDrop(column.status, issueId, toIndex)
          }
          {...(users !== undefined ? { users } : {})}
        />
      ))}
    </div>
  );
}

/**
 * Issue header, description and metadata rail.
 *
 * Must call (do not reimplement): can
 */
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { formatDate, formatRelative, isOverdue } from "@/lib/date";
import { humanizePriority, humanizeStatus } from "@/lib/format";
import { renderMarkdown } from "@/lib/markdown";
import { can } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import type { IssueWithRelations } from "@/types/issue";
import type { Actor, User } from "@/types/member";
import type { ReactElement } from "react";
import { issueResource } from "../permission/resources";
import { PRIORITY_TONE, STATUS_TONE } from "./issue-tone";

export type IssueDetailProps = {
  issue: IssueWithRelations;
  actor: Actor;
  author: User;
  assignee: User | null;
  timeZone?: string;
};

export function IssueDetail(props: IssueDetailProps): ReactElement | null {
  const {
    issue: relations,
    actor,
    author,
    assignee,
    timeZone = "UTC",
  } = props;
  const { issue, labels, commentCount, attachmentCount } = relations;
  const resource = issueResource(issue);

  const mayUpdate = can(actor, "issue:update", resource);
  const mayArchive = can(actor, "issue:archive", resource);
  const archived = isArchived(issue);

  return (
    <article className="issue-detail grid gap-6 md:grid-cols-[1fr_16rem]">
      <div className="min-w-0">
        <header className="mb-4">
          <p className="text-sm text-neutral-500">#{issue.number}</p>
          <h1 className="text-2xl font-semibold">{issue.title}</h1>
          <p className="mt-1 text-sm text-neutral-500">
            {author.name} opened this {formatRelative(issue.createdAt)}
            {" · "}
            {commentCount} comments
            {attachmentCount > 0 ? ` · ${attachmentCount} attachments` : ""}
          </p>
        </header>

        {issue.description === null || issue.description.length === 0 ? (
          <p className="text-neutral-500">No description provided.</p>
        ) : (
          <div
            className="prose max-w-none"
            // The service layer sanitises on write; `renderMarkdown` escapes
            // anything it does not itself emit.
            dangerouslySetInnerHTML={{ __html: renderMarkdown(issue.description) }}
          />
        )}
      </div>

      <aside className="space-y-4 text-sm">
        <section>
          <h2 className="mb-1 font-medium text-neutral-500">Status</h2>
          <Badge tone={STATUS_TONE[issue.status]}>
            {humanizeStatus(issue.status)}
          </Badge>
          {archived ? (
            <Badge tone="warning" size="sm">
              Archived
            </Badge>
          ) : null}
        </section>

        <section>
          <h2 className="mb-1 font-medium text-neutral-500">Priority</h2>
          <Badge tone={PRIORITY_TONE[issue.priority]}>
            {humanizePriority(issue.priority)}
          </Badge>
        </section>

        <section>
          <h2 className="mb-1 font-medium text-neutral-500">Assignee</h2>
          {assignee === null ? (
            <span className="text-neutral-500">Unassigned</span>
          ) : (
            <span className="flex items-center gap-2">
              <Avatar name={assignee.name} src={assignee.avatarUrl} size="xs" />
              {assignee.name}
            </span>
          )}
        </section>

        {labels.length > 0 ? (
          <section>
            <h2 className="mb-1 font-medium text-neutral-500">Labels</h2>
            <div className="flex flex-wrap gap-1">
              {labels.map((label) => (
                <Badge key={label.id} tone="neutral" size="sm">
                  {label.name}
                </Badge>
              ))}
            </div>
          </section>
        ) : null}

        {issue.dueAt !== null ? (
          <section>
            <h2 className="mb-1 font-medium text-neutral-500">Due</h2>
            <span className={
              issue.archivedAt === null &&
              issue.status !== "done" &&
              issue.status !== "canceled" &&
              isOverdue(issue.dueAt, new Date(), timeZone)
                ? "text-red-600"
                : ""
            }>
              {formatDate(issue.dueAt, timeZone)}
            </span>
          </section>
        ) : null}

        {mayUpdate || mayArchive ? (
          <section className="flex gap-2 pt-2">
            {mayUpdate ? (
              <Button variant="secondary" size="sm">
                Edit
              </Button>
            ) : null}
            {mayArchive && !archived ? (
              <Button variant="ghost" size="sm">
                Archive
              </Button>
            ) : null}
          </section>
        ) : null}
      </aside>
    </article>
  );
}

